var prismaBaselineByName = func() map[string]int64 {
	m := make(map[string]int64, len(PrismaBaseline))
	for _, entry := range PrismaBaseline {
		m[entry.PrismaName] = entry.Version
	}
	return m
}()

// LookupPrismaVersion returns the Goose version assigned to a historical Prisma migration.
func LookupPrismaVersion(prismaName string) (int64, bool) {
	v, ok := prismaBaselineByName[prismaName]
	return v, ok
}
